// Read filter configuration
const preferredKeywords = [
  'outbound automation', 'lead generation', 'Apollo', 'Clay',
  'cold email', 'LinkedIn outreach', 'CRM', 'AI automation',
  'sales automation', 'prospecting', 'workflow automation',
  'HubSpot', 'Salesforce'
];

const excludedKeywords = [
  'senior manager', 'field sales', 'door-to-door sales',
  'customer support', 'unpaid internship'
];

const priorityLocations = [
  'Bangalore', 'Bengaluru', 'Hyderabad', 'Chennai',
  'Coimbatore', 'Gurugram', 'Gurgaon', 'Mumbai'
];

const items = $input.all();
const filteredJobs = [];

for (const item of items) {
  const jobTitle = (item.json.title || item.json.jobTitle || '').toLowerCase();
  const description = (item.json.description || item.json.contentSnippet || '').toLowerCase();
  const location = (item.json.location || '').toLowerCase();
  const fullText = `${jobTitle} ${description} ${location}`;

  // Check for excluded keywords (REJECT if found)
  let shouldExclude = false;
  for (const keyword of excludedKeywords) {
    if (fullText.includes(keyword.toLowerCase())) {
      shouldExclude = true;
      break;
    }
  }

  if (shouldExclude) {
    continue; // Skip this job
  }

  // Calculate match score based on preferred keywords
  let matchScore = 0;
  const matchedKeywords = [];

  for (const keyword of preferredKeywords) {
    if (fullText.includes(keyword.toLowerCase())) {
      matchScore += 10;
      matchedKeywords.push(keyword);
    }
  }

  // Bonus points for priority locations
  for (const loc of priorityLocations) {
    if (location.includes(loc.toLowerCase())) {
      matchScore += 20;
      break;
    }
  }

  // Only keep jobs with score >= 30 (at least 3 keyword matches or 1 keyword + location)
  if (matchScore >= 30) {
    filteredJobs.push({
      json: {
        ...item.json,
        matchScore: matchScore,
        matchedKeywords: matchedKeywords.join(', '),
        filterStatus: 'Passed'
      }
    });
  }
}

return filteredJobs;

// Get filtered jobs from previous node
const newJobs = $('Apply Keyword Filter').all();

// Get existing jobs from Google Sheets
const existingJobs = $('Read Existing Jobs from Sheet').all();

// Create a Set of existing job URLs for fast lookup
const existingUrls = new Set();
for (const job of existingJobs) {
  const url = job.json['Job URL'] || job.json.link || job.json.jobUrl;
  if (url) {
    existingUrls.add(url.trim().toLowerCase());
  }
}

// Filter out duplicates
const uniqueJobs = [];
const duplicates = [];

for (const job of newJobs) {
  const url = (job.json.link || job.json.jobUrl || '').trim().toLowerCase();

  if (!url) {
    // No URL - skip this job
    continue;
  }

  if (existingUrls.has(url)) {
    // Duplicate found
    duplicates.push({
      json: {
        ...job.json,
        duplicateStatus: 'Duplicate - Skipped'
      }
    });
  } else {
    // New unique job
    uniqueJobs.push({
      json: {
        ...job.json,
        duplicateStatus: 'New - Added'
      }
    });
    // Add to set to prevent duplicates within this batch
    existingUrls.add(url);
  }
}

// Return only unique jobs
return uniqueJobs;

// Format jobs to match Google Sheets schema
const jobs = $input.all();
const runId = $('Start from Module 2').first().json.runId;
const timestamp = new Date().toISOString().replace('T', ' ').substring(0, 19);

const formattedJobs = jobs.map(job => {
  const data = job.json;

  // Generate unique Job ID
  const platform = data.sourcePlatform || 'Unknown';
  const urlMatch = (data.link || data.jobUrl || '').match(/\d+/);
  const jobId = `${platform.toLowerCase()}-${urlMatch ? urlMatch[0] : Date.now()}`;

  // Extract location
  let location = data.location || '';
  if (location.includes('·')) {
    location = location.split('·')[0].trim();
  }

  // Determine work mode
  const fullText = `${data.title || ''} ${data.description || ''} ${location}`.toLowerCase();
  let workMode = 'On-site';
  if (fullText.includes('remote')) workMode = 'Remote';
  else if (fullText.includes('hybrid')) workMode = 'Hybrid';

  return {
    json: {
      jobId: jobId,
      dateScraped: new Date().toISOString().split('T')[0],
      sourcePlatform: platform,
      jobTitle: data.title || data.jobTitle || 'Unknown',
      companyName: data.creator || data.company || 'Unknown',
      companySize: 'Unknown',
      location: location || 'Not Specified',
      workMode: workMode,
      experienceLevel: 'Mid-Level',
      salaryRange: 'Not Specified',
      jobDescription: (data.contentSnippet || data.description || '').substring(0, 500),
      keySkills: data.matchedKeywords || '',
      jobUrl: data.link || data.jobUrl || '',
      postedDate: data.pubDate ? new Date(data.pubDate).toISOString().split('T')[0] : new Date().toISOString().split('T')[0],
      applicationDeadline: 'Not Specified',
      matchScore: data.matchScore || 0,
      status: 'Discovered',
      resumeLink: '',
      notes: `Filtered and added by automation. Run ID: ${runId}`,
      lastUpdated: timestamp
    }
  };
});

return formattedJobs;
